local({
  subscales <- list(
    proovert = cbind(PCS1, PCS5, PCS12, PCS18, PCS21, PCS24, PCS27, PCS28, PCS33, PCS35),
    reovert = cbind(PCS3, PCS8, PCS11, PCS14, PCS16, PCS20, PCS25, PCS30, PCS36, PCS37),
    prorelat = cbind(PCS2, PCS6, PCS9, PCS13, PCS19, PCS23, PCS26, PCS29, PCS32, PCS39),
    rerelat = cbind(PCS4, PCS7, PCS10, PCS15, PCS17, PCS22, PCS31, PCS34, PCS38, PCS40)
  )
  means <- sapply(subscales, function(items) {
    items[items == 5] <- NA
    if_else(rowSums(!is.na(items)) >= 8, rowMeans(items, na.rm = TRUE), NA_real_)
  })
  rowMeans(means)
})

